diff --git a/src/libicalvcard/vcardstructured.c b/src/libicalvcard/vcardstructured.c
index f526ee70..ba90f5d0 100644
--- a/src/libicalvcard/vcardstructured.c
+++ b/src/libicalvcard/vcardstructured.c
@@ -65,6 +65,10 @@ vcardstructuredtype *vcardstructured_new_from_string(const char *str)
     vcardstructured_ref(st);

     vcardstrarray *field = vcardstrarray_new(2);
+    if (st->num_fields >= VCARD_MAX_STRUCTURED_FIELDS) {
+        vcardstrarray_free(field);
+        return st;
+    }
     st->field[st->num_fields++] = field;

     do {
@@ -78,6 +82,10 @@ vcardstructuredtype *vcardstructured_new_from_string(const char *str)
         if (*str == ';') {
             /* end of field */
             field = vcardstrarray_new(2);
+            if (st->num_fields >= VCARD_MAX_STRUCTURED_FIELDS) {
+                vcardstrarray_free(field);
+                return st;
+            }
             st->field[st->num_fields++] = field;
         }

---
    59  vcardstructuredtype *vcardstructured_new_from_string(const char *str)
    60  {
    61      struct vcardstructuredtype_impl *st = vcardstructured_alloc();
    62      if (!st) {
    63          return st;
    64      }
    65      vcardstructured_ref(st);
    66
    67      vcardstrarray *field = vcardstrarray_new(2);
    68      if (st->num_fields >= VCARD_MAX_STRUCTURED_FIELDS) {
    69          vcardstrarray_free(field);
    70          return st;
    71      }
    72      st->field[st->num_fields++] = field;
    73
    74      do {
    75          char *dequoted_str = vcardvalue_strdup_and_dequote_text(&str, ",;");
    76
    77          if (*str == ',' || field->num_elements || strlen(dequoted_str)) {
    78              vcardstrarray_append(field, dequoted_str);
    79          }
    80          icalmemory_free_buffer(dequoted_str);
    81
    82          if (*str == ';') {
    83              /* end of field */
    84              field = vcardstrarray_new(2);
    85              if (st->num_fields >= VCARD_MAX_STRUCTURED_FIELDS) {
    86                  vcardstrarray_free(field);
    87                  return st;
    88              }
    89              st->field[st->num_fields++] = field;
    90          }
